/* Size and line height come from the profile, so the transcript's measured rows agree with its text. */
.cv-user__bubble {
  background: color-mix(in srgb, var(--agent-text) 5%, var(--agent-page-bg));
  border-radius: 16px;
}

/* Motion: popovers, menus and tooltips enter over 150 ms, folds settle over 200 ms, as the app's do
   (--cmux-motion-micro, --cmux-motion-settle). Animations off and Reduce Motion still win. */
:root {
  --cmux-motion-micro: 150ms;
  --cmux-motion-settle: 200ms;
  --cmux-ease-out: cubic-bezier(0.4, 0, 0.2, 1);
}

