{
  "$schema": "https://cmux.dev/schemas/cmux-app/2.json",
  "manifestVersion": 2,
  "id": "local/customize",
  "name": {
    "en": "Thread workspace"
  },
  "version": "1.0.0",
  "description": "Project and thread rows beside a 736-point chat column, with settlement, editor and project actions, attachments and a searchable model picker.",
  "engines": {
    "cmux": "^2.0"
  },
  "runtime": {
    "main": "main.js"
  },
  "implements": {
    "cmux.hovercard/1": {
      "export": "renderThreadCard"
    },
    "cmux.section/1": {
      "export": "renderProjectPicker",
      "title": "Project picker",
      "symbol": "folder",
      "options": {
        "defaultRegion": "top"
      }
    },
    "cmux.session.info.section/1": {
      "export": "renderEditor",
      "title": "Open in editor",
      "symbol": "chevron.left.forwardslash.chevron.right"
    },
    "cmux.composer.toolbar/1": {
      "options": {
        "buttons": [
          {
            "action": "composer.attachFiles",
            "label": "Attach files"
          }
        ]
      }
    },
    "cmux.composer.model.picker/1": {
      "options": {
        "modelMenu": "search",
        "reasoningMenu": "column"
      }
    }
  },
  "scopes": {
    "project:read": "Search available project folders.",
    "actions:run": "Start a chat in the selected project, choose a folder, or open the active local folder in an editor."
  },
  "activation": [
    "onInterface:cmux.hovercard/1",
    "onInterface:cmux.section/1",
    "onInterface:cmux.session.info.section/1"
  ],
  "files": [
    "main.js"
  ]
}

files.customize/main.js:
// The host supplies the hovered workspace and its activity in ctx.card.
function renderThreadCard({ card }) {
  const project = card.facts.find((fact) => fact.kind === "folder")
  const details = card.facts.filter((fact) =>
    ["needsInput", "branch", "pullRequest", "machine", "agent"].includes(fact.kind)
  )
  return VStack({ spacing: 4, alignment: "leading" }, [
    HStack({ spacing: 6 }, [
      project ? Text(project.text).font("caption").secondary().lineLimit(1) : null,
      Spacer(),
      card.age ? Text(card.age).font("caption").secondary() : null,
    ]),
    Text(card.title).weight("medium").lineLimit(2),
    card.status ? Text(card.status).font("caption") : null,
    ...details.map((fact) => Text(fact.text).font("caption").secondary().lineLimit(2)),
  ])
}

function renderProjectPicker() {
  const [isOpen, setOpen] = signal(false)
  const [query, setQuery] = signal("")
  const [projects, setProjects] = signal([])
  const [status, setStatus] = signal("")
  let request = 0

  async function search(text) {
    const revision = ++request
    setQuery(text)
    setProjects([])
    setStatus("Searching…")
    try {
      const result = await cmux.call("project.list", { query: text.trim(), limit: 25 })
      if (revision !== request) return
      const matches = result.projects.filter((project) => project.state === "present")
      setProjects(matches)
      setStatus(matches.length ? "" : "No matching projects")
    } catch (error) {
      if (revision === request) setStatus(String(error.message || error))
    }
  }

  function togglePicker() {
    setOpen(!isOpen())
    if (isOpen()) search("")
    else request++
  }

  async function openProject(action, args) {
    try {
      await cmux.actions.run(action, args)
      setOpen(false)
      request++
    } catch (error) {
      setStatus(String(error.message || error))
    }
  }

  return VStack({ alignment: "leading", spacing: 4 }, [
    Button("Choose project…", togglePicker),
    () => isOpen() ? VStack({ alignment: "leading", spacing: 3 }, [
      TextField(query, { placeholder: "Search projects", onEdit: search, onCancel: togglePicker }),
      ForEach({ items: projects, key: (project) => project.path }, (project) =>
        Button(
          Row({ title: () => project().name, subtitle: () => project().path, symbol: "folder" }),
          () => openProject("palette.newAgentChat", { cwd: project().path })
        )
      ),
      () => status() ? Text(status()).font("caption") : null,
      Button("Add project…", () => openProject("openFolder", {}))
    ]) : null
  ])
}

function renderEditor() {
  return Button("Open in VS Code", async () => {
    try {
      await cmux.actions.run("palette.terminalOpenDirectory", { app: "com.microsoft.VSCode" })
    } catch (error) {
      cmux.toast({ title: "Couldn’t open the folder", message: String(error.message || error), tone: "warning" })
    }
  })
}

globalThis.__cmuxAppExports = { renderThreadCard, renderProjectPicker, renderEditor }

files.keybindings.json:
// The app's keyboard flows on cmux actions. Each key is scoped to the chat (agentPaneFocused), so a
// terminal keeps cmux's own Command-K (clear), Command-D (split right) and Command-J chords.
[
  // Command palette on Command-K. Chat search (cmux puts it on Command-K) is the sidebar's Search row.
  { "key": "cmd+k", "command": "commandPalette", "when": "agentPaneFocused" },
  // Terminal drawer: cmux's quick terminal shows and hides on the same key.
  { "key": "cmd+j", "command": "toggleQuickTerminal", "when": "agentPaneFocused" },
  // Diff beside the chat.
  { "key": "cmd+d", "command": "openDiffViewer", "when": "agentPaneFocused" },
  // Preview beside the chat.
  { "key": "cmd+shift+j", "command": "agentPane.togglePreview", "when": "agentPaneFocused" },
  // New thread.
  { "key": "cmd+n", "command": "palette.newAgentChat" },
  { "key": "cmd+shift+o", "command": "palette.newAgentChat" },
  // Composer chords: model, effort, access, worktree, host.
  { "key": "cmd+shift+m", "command": "agentPane.switchModel", "when": "agentPaneFocused" },
  { "key": "cmd+shift+e", "command": "agentPane.setEffort", "when": "agentPaneFocused" },
  { "key": "cmd+shift+a", "command": "agentPane.composer.switchMode", "when": "agentPaneFocused" },
  { "key": "cmd+shift+x", "command": "agentPane.composer.chooseFolder", "when": "agentPaneFocused" },
  { "key": "cmd+shift+h", "command": "agentPane.composer.chooseComputer", "when": "agentPaneFocused" },
  // Previous and next thread; Command-1 to 9 already jump.
  { "key": "cmd+shift+leftbracket", "command": "prevSidebarTab" },
  { "key": "cmd+shift+rightbracket", "command": "nextSidebarTab" },
  // Settle a finished thread, pin a thread.
  { "key": "cmd+shift+s", "command": "markWorkspaceDone", "when": "agentPaneFocused" },
  { "key": "cmd+shift+p", "command": "palette.toggleTabPin", "when": "agentPaneFocused" },
  // Dictation.
  { "key": "cmd+shift+d", "command": "palette.toggleDictation", "when": "agentPaneFocused" },
  // Usage: the context meter is the nearest cmux has to the app's usage page.
  { "key": "cmd+u", "command": "agentPane.composer.showContextUsage", "when": "agentPaneFocused" },
  // Keyboard shortcuts.
  { "key": "cmd+slash", "command": "palette.searchShortcuts" }
]
